```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT metric, service_name, min(value) AS min_avail, max(value) AS max_avail, count(*) AS n FROM abnormal_metrics WHERE metric='k8s.deployment.available' AND service_name='search' GROUP BY ALL",
          "claim": "search deployment available stays at 0 for the whole abnormal window, versus 1 in normal."
        },
        {
          "kind": "metric",
          "sql": "SELECT time, attr_k8s_pod_name AS pod, value FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE 'search%' ORDER BY time",
          "claim": "search pod restart count climbs from 9 to 12 during the abnormal window; normal baseline is a steady 7."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) AS n, quantile_cont(duration,0.5)/1e6 AS p50_ms FROM abnormal_traces WHERE span_name='search.Search/Nearby' GROUP BY ALL",
          "claim": "frontend's calls to search.Search/Nearby all return Error in about 0.01 ms; search emits no server spans in the abnormal window."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_http_response_status_code AS sc, attr_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='frontend' AND span_name='HTTP /hotels' GROUP BY ALL",
          "claim": "All 271 frontend HTTP /hotels requests return 500 in abnormal, versus 1055 successful (200) in normal."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) AS n, quantile_cont(duration,0.5)/1e6 AS p50_ms FROM abnormal_traces WHERE span_name IN ('search.Search/Nearby','HTTP /hotels') GROUP BY ALL",
          "claim": "Frontend's search.Search/Nearby client calls fail fast and its HTTP /hotels server spans return 500 in the same window."
        }
      ]
    }
  ]
}
```

